'use strict';
// Draft generated by FreeLLMAPI (dots-3-note-preview); reviewed by Claude.
const schemas = require('../validators/accountValidators');
const accountService = require('../services/accountService');
const asyncHandler = require('../utils/asyncHandler');

const ok = (res, data, status) => res.status(status || 200).json({ success: true, data });

exports.sessions = asyncHandler(async (req, res) => {
  const current = req.headers['x-refresh-token'];
  ok(res, { sessions: await accountService.listSessions(req.user.id, current) });
});

exports.revokeSession = asyncHandler(async (req, res) => {
  const { familyId } = schemas.sessionParams.parse(req.params);
  await accountService.revokeSession(req.user.id, familyId);
  ok(res, { revoked: true });
});

exports.changeEmail = asyncHandler(async (req, res) => {
  const { password, newEmail } = schemas.changeEmail.parse(req.body);
  ok(res, await accountService.changeEmail(req.user.id, password, newEmail));
});

exports.deactivate = asyncHandler(async (req, res) => {
  const { password } = schemas.confirmPassword.parse(req.body);
  await accountService.deactivateAccount(req.user.id, password);
  ok(res, { deactivated: true });
});

exports.deleteAccount = asyncHandler(async (req, res) => {
  const { password } = schemas.confirmPassword.parse(req.body);
  await accountService.deleteAccount(req.user.id, password);
  ok(res, { deleted: true });
});
